    // Ten goc cua 2 file Language_en.properties va Language_vi.properties
    public static final String LANGUAGE_FILE = "constants/Language";

    // Do dai captcha
    public static final int CAPTCHA_LENGTH = 5;

    // Cac ky tu duoc dung de sinh captcha
