package utils;

import constants.Constants;
import java.util.Random;

/**
 * Sinh captcha ngau nhien cho moi lan dang nhap (ham generateCaptcha cua de; Guide: CapchaUtils).
 *
 * @author CuongThai Academy
 */
public final class CaptchaUtils {

    // Constructor private: lop chi co ham static (checklist 3.4)
    private CaptchaUtils() {
    }

    // Sinh 1 chuoi captcha gom chu hoa, chu thuong va so (Random -> vi tri -> char)
    public static String generateCaptcha() {
        StringBuilder captchaBuilder = new StringBuilder();
        Random random = new Random();
        int index = 0;

        // Moi vong lay ngau nhien 1 ky tu trong bang ky tu
        for (int i = 0; i < Constants.CAPTCHA_LENGTH; i++) {
            index = random.nextInt(Constants.CAPTCHA_CHARACTERS.length());
            captchaBuilder.append(Constants.CAPTCHA_CHARACTERS.charAt(index));
        }

        return captchaBuilder.toString();
    }
}

