package utils;

import constants.Constants;
import constants.Message;

/**
 * Kiem tra chu nguoi dung go vao. Sai thi nem Exception kem cau bao loi theo ngon ngu.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Ngan khong cho tao doi tuong Validation
    private Validation() {
    }

    // Doi chu thanh so nguyen va kiem so nam trong [min, max]
    public static int getInt(String input, int min, int max) throws Exception {
        int number = 0;

        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            number = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu hoac de trong thi bao phai nhap so
            throw new Exception(Message.getInvalidNumberError());
        }

        // So ngoai khoang thi bao khoang dung
        if ((number < min) || (number > max)) {
            throw new Exception(String.format(Message.getRangeError(), min, max));
        }

        return number;
    }

    // Kiem so tai khoan: dung 10 chu so (ham checkAccountNumber cua de)
    public static String checkAccountNumber(String accountNumber) throws Exception {
        String text = accountNumber.trim();

        // Khong khop regex 10 chu so thi bao loi
        if (!text.matches(Constants.ACCOUNT_NUMBER)) {
            throw new Exception(Message.getAccountInvalid());
        }

        return text;
    }

    // Kiem mat khau: 8-31 ky tu, co ca chu va so (ham checkPassword cua de)
    public static String checkPassword(String password) throws Exception {
        // Khong khop regex mat khau thi bao loi
        if (!password.matches(Constants.PASSWORD)) {
            throw new Exception(Message.getPasswordInvalid());
        }

        return password;
    }

    // Kiem captcha: chuoi go vao khong rong va nam trong captcha (dung contains() nhu de)
    public static void checkCaptcha(String input, String captcha) throws Exception {
        String text = input.trim();

        // Rong hoac khong nam trong captcha thi bao sai
        if ((text.isEmpty()) || (!captcha.contains(text))) {
            throw new Exception(Message.getCaptchaInvalid());
        }
    }
}

